/**
 * The committed calibration corpus: a handful of synthetic records in UEyes shape, and the
 * loader every later ticket of step #11 reads them through.
 *
 * **These records are synthetic.** The auto-decision on #11 settles it: this repository
 * vendors no UEyes bytes, so the corpus is generated by committed code
 * (`scripts/make-corpus.ts`) and shaped exactly as a converted UEyes record (#86) — the
 * ground truth #81 declares, nothing added and nothing left out. Pointing the same metric,
 * baseline or scoring code at the real downloaded dataset changes the data and not a line
 * of the code. A figure measured on these records is **not** a published UEyes score;
 * `docs/corpus.md` says what each record exists to prove, and #89 asserts the label is in
 * a report's heading rather than its footnote.
 *
 * Geometry is image space, as `src/types.ts` fixes it: the origin is the image's top-left
 * pixel, `x` runs right, `y` runs down. The maps are `sum-to-one`.
 *
 * A record's bytes are two committed files in `test/corpus/`: `<name>.json`, which is the
 * record with its absolute `imagePath` left out, and `<name>.png`, the image. The path is
 * left out because it differs per machine and a committed absolute path would be a lie;
 * the loader fills it in. The test material lives under `test/` because that is what it is
 * for — CI, with no download — and this loader is `src/` because the metrics, the
 * baselines and the scoring (#83, #84, #87, #88) read it through the package's entry
 * point.
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { RECORD_CATEGORIES } from './types.js';
import type { GroundTruthRecord, RecordCategory } from './types.js';

/**
 * The committed records, and the property each one exists for. A later ticket names a
 * record; it does not invent an input, so a behavioural claim ("an over-confident
 * prediction is punished") is made about material the whole step shares.
 *
 * The generator keys its specs by `CorpusRecordName`, so a name added here without a spec
 * fails to compile rather than at some later ticket's first read.
 */
export const CORPUS_RECORD_NAMES = [
  /**
   * One bright region on a flat field, with the human map and three human scanpaths
   * concentrated on it: the case a working predictor must score well on, and — because the
   * three participants agree in part and not in whole — the record the human-to-human
   * agreement ceiling (#84) is measurable on.
   */
  'webpage-bright-hero',
  /**
   * Two equally bright panels, with both participants visiting the left one before the
   * right: the case an order-sensitive metric (#84) can see and a location-only metric
   * (#83) cannot.
   */
  'desktop-two-panels',
  /**
   * The degenerate record: one participant, one fixation, a one-second viewing cut. The
   * edge case lives in the corpus and not only in a unit test.
   */
  'mobile-single-fixation',
  /**
   * A uniform field with a diffuse human map: nothing should stand out, so an
   * over-confident prediction scores badly and a metric has something to punish.
   */
  'poster-uniform-field',
] as const;

export type CorpusRecordName = (typeof CORPUS_RECORD_NAMES)[number];

/**
 * A committed record as it sits on disk: the ground truth with the absolute `imagePath`
 * left out, which the loader supplies.
 */
export type CorpusRecordData = Omit<GroundTruthRecord, 'imagePath'>;

/** The directory the corpus files are committed in. */
export const CORPUS_DIR = fileURLToPath(new URL('../test/corpus/', import.meta.url));

/** A corpus that does not hold together, or a name that is not in it. */
export class CorpusError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CorpusError';
  }
}

/** The two committed files of one record. The only place these paths are decided. */
export const corpusRecordPaths = (
  name: CorpusRecordName,
): { readonly data: string; readonly image: string } => ({
  data: join(CORPUS_DIR, `${name}.json`),
  image: join(CORPUS_DIR, `${name}.png`),
});

const isCorpusRecordName = (name: string): name is CorpusRecordName =>
  (CORPUS_RECORD_NAMES as readonly string[]).includes(name);

const isRecordCategory = (category: string): category is RecordCategory =>
  (RECORD_CATEGORIES as readonly string[]).includes(category);

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

/** The `width` × `height` of a value that should be a size, or `null` when it is not one. */
const sizeOf = (value: unknown): { readonly width: number; readonly height: number } | null =>
  isObject(value) &&
  typeof value.width === 'number' &&
  typeof value.height === 'number' &&
  value.width > 0 &&
  value.height > 0
    ? { width: value.width, height: value.height }
    : null;

/**
 * Checks what the loader itself depends on — that the file is the record it is named
 * after, with an image, a map of the stated size and at least one scanpath — and then
 * trusts the bytes.
 *
 * It is deliberately not a schema validator: the generator is the only thing that writes
 * these files and `test/corpus.test.ts` asserts both that the committed bytes are the
 * generator's output and every invariant a later ticket reads without re-checking. What
 * this catches is the realistic accident — a truncated file, a half-finished rebase, a
 * record renamed on one side only — loudly, at the read, instead of as a strange figure
 * three tickets later.
 */
export const parseCorpusRecordData = (
  name: CorpusRecordName,
  parsed: unknown,
): CorpusRecordData => {
  const fail = (expectation: string): never => {
    throw new CorpusError(`corpus record ${name} is malformed: ${expectation}`);
  };
  if (!isObject(parsed)) return fail('it is not an object');
  if (parsed.id !== name) return fail(`its id is ${JSON.stringify(parsed.id)}, not its name`);
  if (typeof parsed.category !== 'string' || !isRecordCategory(parsed.category)) {
    return fail(`${JSON.stringify(parsed.category)} is not one of ${RECORD_CATEGORIES.join(', ')}`);
  }
  if (sizeOf(parsed.imageSize) === null) return fail('imageSize is not a positive size');
  const map = parsed.saliencyMap;
  const mapSize = sizeOf(map);
  if (!isObject(map) || mapSize === null) return fail('saliencyMap has no positive resolution');
  const cells = mapSize.width * mapSize.height;
  if (!Array.isArray(map.values) || map.values.length !== cells) {
    return fail(`saliencyMap.values is not ${cells} cells`);
  }
  if (!Array.isArray(parsed.scanpaths) || parsed.scanpaths.length === 0) {
    return fail('it carries no scanpath');
  }
  return parsed as unknown as CorpusRecordData;
};

/**
 * One record by name, with its `imagePath` resolved to the committed image.
 *
 * The argument is a `string` rather than a `CorpusRecordName` because a name reaching this
 * from a CLI flag or a report's configuration has not been through the compiler: an
 * unknown one fails here, naming the records that exist.
 */
export const loadCorpusRecord = (name: string): GroundTruthRecord => {
  if (!isCorpusRecordName(name)) {
    throw new CorpusError(
      `no corpus record named ${JSON.stringify(name)}; the corpus holds ${CORPUS_RECORD_NAMES.join(', ')}`,
    );
  }
  const paths = corpusRecordPaths(name);
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(paths.data, 'utf8'));
  } catch (cause) {
    throw new CorpusError(`corpus record ${name} is unreadable at ${paths.data}: ${String(cause)}`);
  }
  return { ...parseCorpusRecordData(name, parsed), imagePath: paths.image };
};

/** Every record, in the order `CORPUS_RECORD_NAMES` declares. */
export const loadCorpus = (): readonly GroundTruthRecord[] =>
  CORPUS_RECORD_NAMES.map((name) => loadCorpusRecord(name));

/**
 * Every record of one category, in corpus order. Each of the four categories holds at
 * least one record, so this never comes back empty — an unknown category does not come
 * back at all.
 */
export const loadCorpusCategory = (category: string): readonly GroundTruthRecord[] => {
  if (!isRecordCategory(category)) {
    throw new CorpusError(
      `no corpus category named ${JSON.stringify(category)}; the categories are ${RECORD_CATEGORIES.join(', ')}`,
    );
  }
  return loadCorpus().filter((record) => record.category === category);
};
